$(function(){ const items=[['数据库 SQL 入门','数据库'],['jQuery 交互实践','前端'],['Git 协作指南','工具']];function draw(){ $('#cards').empty();items.filter(x=>x[0].includes($('#search').val())&&($('#category').val()==='全部'||x[1]===$('#category').val())).forEach(x=>$('<article class="card">').append($('<span class="tag">').text(x[1]),$('<h3>').text(x[0]),$('<p>').text('点击资源卡片查看学习目标与课程笔记。')).appendTo('#cards'));$('#result').text('原型演示：筛选、主题和成员展开可操作');}$('#search').on('input',draw);$('#category').on('change',draw);$('#expand').on('click',()=>$('#details').slideToggle());$('#theme').on('click',()=>$('body').toggleClass('dark'));$('#messageForm').on('submit',e=>{e.preventDefault();$('#feedback').addClass('notice').text('原型提交成功，本页面不保存数据');});$('#load').on('click',draw);draw();});